"""Independent H1-H6 walk. Real stream receipts regenerated by build_fixture.py."""
import sys,json,math,subprocess,os
from pathlib import Path
from copy import deepcopy as cp
R=Path(__file__).resolve().parent; ROOT=R.parents[1];sys.path.insert(0,str(ROOT))
from scripts import bytes_stream_test as p
D=json.loads((R/'e2e-positive/input_A_knee_found.json').read_text())
for rec in D['records']:
 r,h=rec['receipt'],rec['harvest']
 for span in ('pre','post'):
  st=r['idle_'+span+'_start_ns']
  for k,rows in h['idle'][span].items():
   mean=math.fsum(x['power_w'] for x in rows)/len(rows); step=7_200_000_000
   h['idle'][span][k]=[dict({'stamp_ns':st+i*step} if k in ('meter','battery') else {'start_ns':st+i*step,'end_ns':st+(i+1)*step},power_w=mean) for i in range(8)]
 h['battery_samples']=cp(h['idle']['pre']['battery']+h['idle']['post']['battery'])

def read(d):return p.read_known_bytes(cp(d['records']),cp(d['scan']))
def bounds(o):
 out={('aggregate',b):v['halfwidth'] for b,v in o['boundaries'].items() if isinstance(v.get('halfwidth'),(int,float))}
 for i,c in enumerate(o['calls']):
  for b,v in c['boundaries'].items():
   for f in ('bound_j','baseline_bound_j','edge_bound_j'):
    if isinstance(v.get(f),(int,float)):out[(i,b,f)]=v[f]
 return out
B=read(D);BB=bounds(B);classes=lambda o:{k:v['class'] for k,v in o['boundaries'].items()}
assert all(c=='RESOLVED' for c in classes(B).values()),classes(B)
def leaves(o,path=()):
 if isinstance(o,dict):
  for k,v in o.items():yield from leaves(v,path+(k,))
 elif isinstance(o,list):
  for i,v in enumerate(o):yield from leaves(v,path+(i,))
 else:yield path,o
cases=[]
for path,v in leaves(D):
 if type(v) in (float,int):cases.append((path,10**400,'huge'))
 if path[-1]=='power_w' and path[-3] in ('rails','gpu','meter') or path[-2:]==('energy_j','rails'):
  cases.append((path,-abs(v)-1,'negative'))
 if 'stack' in path or 'capture_stack' in path:
  f='.'.join(str(k) for k in path[path.index('stack')+1:] if isinstance(k,str)) if 'stack' in path else '.'.join(str(k) for k in path[path.index('capture_stack')+1:] if isinstance(k,str))
  if f in ('python','kernel_library') or f=='telemetry_backend' and 'capture_stack' in path or f.startswith('packages.') and f not in ('packages.mlx','packages.mlx-metal'):
   cases.append((path,{},'disclosure'))
for i,rec in enumerate(D['records']):
 keys=('idle_pre_start_ns','idle_pre_end_ns','start_ns','end_ns','idle_post_start_ns','idle_post_end_ns')
 for a,b in zip(keys,keys[1:]):
  cases.extend([(('records',i,'receipt',b),rec['receipt'][a]-(b!='end_ns'),'order'),(('records',i,'receipt',b),0,'zero')])
 for sp,block in rec['harvest']['idle'].items():
  for k,rows in block.items():
   for j,row in enumerate(rows):
    root=('records',i,'harvest','idle',sp,k,j)
    if 'end_ns' in row:
     for v in (row['start_ns'],row['start_ns']-1,0):cases.append((root+('end_ns',),v,'order'))
     cases.append((root+('start_ns',),0,'zero'))
    else:cases.append((root+('stamp_ns',),0,'zero'))
 for j,row in enumerate(rec['harvest']['battery_samples']):cases.append((('records',i,'harvest','battery_samples',j,'stamp_ns'),0,'zero'))
cases += [(('scan','status'),v,'status') for v in (None,7)]
if '--recheck' in sys.argv:
 paths={tuple(x[0]) for x in json.loads((R/'independent-summary.json').read_text())['failures']}
 cases=[c for c in cases if c[0] in paths]
fail=[]
print('starting independent cases',len(cases),flush=True)
for n,(path,value,mode) in enumerate(cases):
 d=cp(D);o=d
 for k in path[:-1]:o=o[k]
 o[path[-1]]=value
 try:
  out=read(d);assert len(out['calls'])==8;assert out['input_records']==d['records']
  for k,v in bounds(out).items():assert v>=BB[k],(k,v,BB[k])
  if mode=='disclosure':
   assert classes(out)==classes(B)
   assert out['boundaries']==B['boundaries']
   assert 'not recorded (' in json.dumps(out['stack_comparisons'])
  else:
   consumed=(path[0]=='scan' and path[1] in ('status','K','B','Bc1','Bc3','Bc2') or
    path[0]=='records' and (path[2]=='receipt' and path[3] in p.RECEIPT_INPUTS or
    path[2]=='harvest' and path[3] in ('energy_j','idle','tau_s','r_max_s','anchor_shift_j','meter_edge_w','battery_edge_j','battery_samples')))
   if consumed:
    leaf=next(k for k in reversed(path) if isinstance(k,str))
    assert any(leaf in r for r in out['reasons']),(path,out['reasons'])
    assert 'UNDETERMINED' in classes(out).values(),(path,classes(out))
  if n%97==0:
   f=R/f'independent-current-{os.getpid()}.json';f.write_text(json.dumps(d))
   pr=subprocess.run([sys.executable,'-B',str(ROOT/'scripts/bytes_stream_test.py'),'read',str(f)],capture_output=True,text=True)
   assert pr.returncode==0,pr.stderr
   assert json.loads(pr.stdout)==json.loads(json.dumps(out))
 except Exception as e:fail.append((path,mode,repr(e)))
print('independent cases',len(cases),'failures',len(fail),flush=True)
for f in fail:print(f,flush=True)
# Every single lost arm, including every position, with all available coefficients unchanged.
for i in range(8):
 d=cp(D);arm=B['calls'][i]['arm'];d['records'][i]={};o=read(d)
 for beta,v in o['boundaries'].items():
  assert v['class']=='UNDETERMINED'
  expected=('gamma_c','alpha','gamma_d','delta') if arm=='C3' else ('gamma_c','alpha') if arm=='S' else ()
  for key in expected:assert v[key]==B['boundaries'][beta][key],(i,beta,key)
print('H4 all 8 positions / 4 boundaries: PASS')
for path in [('records',0,'harvest','battery_edge_j',0),('records',0,'harvest','energy_j','battery'),('records',0,'harvest','idle','pre','battery',0,'power_w'),('records',0,'harvest','battery_samples',0,'power_w')]:
 d=cp(D);o=d
 for k in path[:-1]:o=o[k]
 o[path[-1]]=-1
 out=read(d);assert not any('missing or invalid' in r and 'battery' in r for r in out['reasons'])
print('signed battery edge, energy, idle power, native poll: PASS')
(R/('recheck-summary.json' if '--recheck' in sys.argv else 'independent-summary.json')).write_text(json.dumps({'cases':len(cases),'failures':fail},default=str))
assert not fail
